'use client';

import { AnimatePresence } from 'motion/react';
import { useEffect, useRef } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { countOf } from '@/registry/ndeko/lib/words';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { ENTRIES, SECTION } from './data';
import { EntryRow } from './entry-row';
import { TypeFilters } from './filters';
import { entryCountOf, groupsOf } from './groups';
import { linkOf, useLinkedEntry } from './hash';
import { MonthNav } from './month-nav';
import {
  COPIED_MS,
  INITIAL,
  LOOP_AFTER_MS,
  monthKeyOf,
  reducer,
  RESTING,
  SCRIPT,
} from './session';
import { useMonthSpy } from './use-month-spy';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

/** An entry stops under the sticky month heading instead of behind it. */
const HEADING_HEIGHT_PX = 56;

function scrollBehaviorOf(shouldReduceMotion: boolean): ScrollBehavior {
  if (shouldReduceMotion) {
    return 'auto';
  }
  return 'smooth';
}

function offsetOf(jumpKey: string) {
  if (jumpKey.startsWith('entry-')) {
    return HEADING_HEIGHT_PX;
  }
  return 0;
}

export default function Changelog02() {
  const {
    ref,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
    takeOver,
  } = useSession(SESSION);
  const frameRef = useRef<HTMLDivElement>(null);
  const shouldReduceMotion = usePrefersReducedMotion();
  const linkedFromAddress = useLinkedEntry();
  const groups = groupsOf(state.filter);
  const monthsKey = groups.map((group) => group.id).join(',');
  const spiedId = useMonthSpy(frameRef, monthsKey);
  const firstId = groups[0]?.id ?? null;
  const activeId = spiedId ?? firstId;
  const shownCount = entryCountOf(groups);
  const { copiedId, jumpKey, jumpRequest } = state;
  const copyLine = 'Link copied';
  const countLine = `${countOf(shownCount, 'update')} shown`;
  let line = countLine;
  if (copiedId !== null) {
    line = copyLine;
  }
  const message = spokenUnless(isAutoplaying, line);
  const canReplay = isFinished && !isAutoplaying;

  useEffect(() => {
    if (linkedFromAddress === null) {
      return;
    }
    takeOver();
    act({ type: 'linked', id: linkedFromAddress });
  }, [linkedFromAddress, takeOver, act]);

  useEffect(() => {
    if (jumpRequest === 0 || jumpKey === null) {
      return;
    }
    const frame = frameRef.current;
    const target = frame?.querySelector<HTMLElement>(
      `[data-anchor="${jumpKey}"]`
    );
    if (!frame || !target) {
      return;
    }
    const top = target.offsetTop - offsetOf(jumpKey);
    const behavior = scrollBehaviorOf(shouldReduceMotion);
    frame.scrollTo({ top, behavior });
  }, [jumpKey, jumpRequest, shouldReduceMotion]);

  useEffect(() => {
    if (copiedId === null) {
      return;
    }
    const timer = setTimeout(() => act({ type: 'copyCleared' }), COPIED_MS);
    return () => clearTimeout(timer);
  }, [copiedId, act]);

  async function copyLink(entryId: string) {
    try {
      await navigator.clipboard.writeText(linkOf(entryId));
    } catch {
      return;
    }
    act({ type: 'copied', id: entryId });
  }

  /** A wheel or a trackpad scrolling the frame is a person reading: the demonstration stops for good. */
  function yieldToWheel() {
    if (isAutoplaying) {
      takeOver();
    }
  }

  function replay() {
    frameRef.current?.scrollTo({ top: 0 });
    restart();
  }

  return (
    <div
      ref={ref}
      className='bg-background text-foreground @container flex h-dvh min-h-[34rem] w-full flex-col'
    >
      <header className='shrink-0 px-4 pt-6 pb-3 @2xl:px-8 @2xl:pt-8'>
        <div className='mx-auto flex w-full max-w-3xl flex-col gap-4'>
          <div className='flex items-start justify-between gap-3'>
            <div className='flex flex-col gap-1'>
              <h2 className='text-2xl font-semibold text-balance'>
                {SECTION.title}
              </h2>
              <p className='text-muted-foreground text-[13px]'>
                {SECTION.description}
              </p>
            </div>
            <div className='flex shrink-0 items-center gap-2'>
              <ReplayButton
                isShown={canReplay}
                onReplay={replay}
                label='Replay'
              />
              <Badge variant='secondary'>{SECTION.badge}</Badge>
            </div>
          </div>
          <div className='flex flex-wrap items-center justify-between gap-3'>
            <TypeFilters
              filter={state.filter}
              pressed={pressed}
              onPick={(filter) => act({ type: 'filterPicked', filter })}
            />
            <MonthNav
              groups={groups}
              activeId={activeId}
              pressed={pressed}
              onJump={(monthId) =>
                act({ type: 'jumped', key: monthKeyOf(monthId) })
              }
            />
          </div>
        </div>
      </header>
      <div
        ref={frameRef}
        onWheel={yieldToWheel}
        tabIndex={0}
        role='region'
        aria-label='Release notes'
        className='focus-visible:ring-ring/25 relative min-h-0 flex-1 overflow-y-auto overscroll-contain px-4 outline-none focus-visible:ring-[3px] focus-visible:ring-inset @2xl:px-8'
      >
        <div className='mx-auto max-w-3xl pb-16'>
          {groups.map((group) => (
            <section
              key={group.id}
              data-month={group.id}
              data-anchor={monthKeyOf(group.id)}
              aria-labelledby={`${group.id}-heading`}
            >
              <h3
                id={`${group.id}-heading`}
                className='bg-background sticky top-0 z-10 flex items-baseline gap-2 py-3 text-sm font-semibold'
              >
                {group.label}
                <span className='text-muted-foreground text-xs font-normal tabular-nums'>
                  {countOf(group.entries.length, 'update')}
                </span>
              </h3>
              <ol>
                <AnimatePresence initial={false}>
                  {group.entries.map((entry) => (
                    <EntryRow
                      key={entry.id}
                      entry={entry}
                      isOpen={state.openIds.includes(entry.id)}
                      isCopied={copiedId === entry.id}
                      pressed={pressed}
                      onToggle={(id) => act({ type: 'toggled', id })}
                      onCopy={copyLink}
                    />
                  ))}
                </AnimatePresence>
              </ol>
            </section>
          ))}
          {groups.length === 0 && (
            <div className='flex flex-col items-start gap-3 py-8'>
              <p className='text-muted-foreground text-sm'>
                No updates of this kind yet, out of {ENTRIES.length} in all.
              </p>
              <Button
                variant='outline'
                onClick={() => act({ type: 'filterPicked', filter: 'all' })}
              >
                Show every update
              </Button>
            </div>
          )}
        </div>
      </div>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { motion } from 'motion/react';
import { useId } from 'react';

import { WordRoll } from '@/components/core/word-roll';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import {
  CheckIcon,
  ChevronDownIcon,
  LinkIcon,
} from '@/registry/ndeko/lib/icons';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap, Fold } from '@/registry/ndeko/ui/chat-motion';
import { Chip } from '@/registry/ndeko/ui/chip';

import { KIND_STYLES, type Entry } from './data';
import { dayLabelOf } from './groups';
import { anchorOf } from './hash';
import { entryKeyOf } from './session';

const DETAIL_LABELS = ['Show details', 'Hide details'];

function detailLabelOf(isOpen: boolean) {
  if (isOpen) {
    return 'Hide details';
  }
  return 'Show details';
}

function chevronClassOf(isOpen: boolean) {
  if (isOpen) {
    return 'rotate-180';
  }
  return undefined;
}

type EntryRowProps = {
  entry: Entry;
  isOpen: boolean;
  isCopied: boolean;
  pressed: string | null;
  onToggle: (entryId: string) => void;
  onCopy: (entryId: string) => void;
};

export function EntryRow({
  entry,
  isOpen,
  isCopied,
  pressed,
  onToggle,
  onCopy,
}: EntryRowProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const detailsId = useId();
  const kind = KIND_STYLES[entry.kind];
  const detailLabel = detailLabelOf(isOpen);

  return (
    <motion.li
      id={anchorOf(entry.id)}
      data-anchor={entryKeyOf(entry.id)}
      {...rowPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <article className='grid gap-2 px-1.5 py-4 @2xl:grid-cols-[6rem_minmax(0,1fr)] @2xl:gap-6'>
        <time
          dateTime={entry.date}
          className='text-muted-foreground text-[13px] tabular-nums @2xl:pt-1'
        >
          {dayLabelOf(entry.date)}
        </time>
        <div className='flex min-w-0 flex-col gap-2'>
          <div className='flex items-start gap-2'>
            <h4 className='min-w-0 flex-1 text-base font-semibold text-balance'>
              {entry.title}
            </h4>
            <Button
              type='button'
              variant='ghost'
              size='icon-sm'
              aria-label={`Copy the link to ${entry.title}`}
              onClick={() => onCopy(entry.id)}
              className={cn(
                'text-muted-foreground shrink-0',
                pressedQuietOf(pressed === `copy-${entry.id}`)
              )}
            >
              <Swap swapKey={String(isCopied)}>
                {isCopied && <CheckIcon />}
                {!isCopied && <LinkIcon />}
              </Swap>
            </Button>
          </div>
          <div>
            <Chip color={kind.color}>{kind.label}</Chip>
          </div>
          <p className='text-muted-foreground text-sm text-pretty'>
            {entry.summary}
          </p>
          <Fold open={isOpen} id={detailsId}>
            <ul className='flex flex-col gap-1.5 pt-1 text-[13px]'>
              {entry.changes.map((change) => (
                <li key={change} className='flex items-baseline gap-2.5'>
                  <span
                    aria-hidden='true'
                    className='bg-foreground/25 size-1 shrink-0 -translate-y-[0.2em] rounded-full'
                  />
                  {change}
                </li>
              ))}
            </ul>
          </Fold>
          <Button
            type='button'
            variant='ghost'
            size='sm'
            aria-expanded={isOpen}
            aria-controls={detailsId}
            onClick={() => onToggle(entry.id)}
            className={cn(
              'text-primary-ink self-start',
              pressedQuietOf(pressed === `toggle-${entry.id}`)
            )}
          >
            <WordRoll text={detailLabel} labels={DETAIL_LABELS} />
            <ChevronDownIcon
              className={cn(
                'transition-transform duration-200 ease-(--ease-out-strong)',
                chevronClassOf(isOpen)
              )}
            />
          </Button>
        </div>
      </article>
    </motion.li>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { FILTERS, type TypeFilter } from './data';
import { countOfKind } from './groups';

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

function filterOf(value: unknown) {
  const filter = FILTERS.find((candidate) => candidate.id === value);
  return filter?.id;
}

type TypeFiltersProps = {
  filter: TypeFilter;
  pressed: string | null;
  onPick: (filter: TypeFilter) => void;
};

export function TypeFilters({ filter, pressed, onPick }: TypeFiltersProps) {
  const pressedValues = [filter];

  function changeFilter(nextValues: unknown[]) {
    const [next] = nextValues;
    const picked = filterOf(next);
    if (picked) {
      onPick(picked);
    }
  }

  return (
    <div className='relative -mx-4 overflow-x-auto px-4 @2xl:mx-0 @2xl:px-0'>
      <ToggleGroup
        aria-label='Kind of change'
        value={pressedValues}
        onValueChange={changeFilter}
        travel
        size='sm'
        indicatorClassName={THUMB}
        className='bg-foreground/[0.05] rounded-lg p-0.5'
      >
        {FILTERS.map((item) => (
          <ToggleGroupItem
            key={item.id}
            value={item.id}
            className={cn(
              'h-7 gap-1.5 rounded-md px-2.5 text-xs',
              pressedQuietOf(pressed === `filter-${item.id}`)
            )}
          >
            {item.label}
            <span className='text-muted-foreground tabular-nums'>
              {countOfKind(item.id)}
            </span>
          </ToggleGroupItem>
        ))}
      </ToggleGroup>
    </div>
  );
}

'use client';

import { useEffect, useRef } from 'react';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import type { MonthGroup } from './groups';

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

type MonthNavProps = {
  groups: MonthGroup[];
  activeId: string | null;
  pressed: string | null;
  onJump: (monthId: string) => void;
};

/** The strip keeps the active month in view by moving itself, never the page. */
function centerActive(strip: HTMLElement) {
  const active = strip.querySelector<HTMLElement>('[data-pressed]');
  if (!active) {
    return;
  }
  const middle = active.offsetLeft + active.offsetWidth / 2;
  const left = middle - strip.clientWidth / 2;
  strip.scrollTo({ left, behavior: 'smooth' });
}

export function MonthNav({ groups, activeId, pressed, onJump }: MonthNavProps) {
  const stripRef = useRef<HTMLDivElement>(null);
  const pressedValues = [activeId ?? ''];

  useEffect(() => {
    const strip = stripRef.current;
    if (strip) {
      centerActive(strip);
    }
  }, [activeId]);

  function changeMonth(nextValues: unknown[]) {
    const [next] = nextValues;
    const group = groups.find((candidate) => candidate.id === next);
    if (group) {
      onJump(group.id);
    }
  }

  return (
    <nav aria-label='Jump to a month' className='min-w-0'>
      <div
        ref={stripRef}
        className='relative -mx-4 overflow-x-auto px-4 @2xl:mx-0 @2xl:px-0'
      >
        <ToggleGroup
          aria-label='Months'
          value={pressedValues}
          onValueChange={changeMonth}
          travel
          size='sm'
          indicatorClassName={THUMB}
          className='bg-foreground/[0.05] rounded-lg p-0.5'
        >
          {groups.map((group) => (
            <ToggleGroupItem
              key={group.id}
              value={group.id}
              className={cn(
                'h-7 rounded-md px-2.5 text-xs',
                pressedQuietOf(pressed === `month-${group.id}`)
              )}
            >
              {group.label}
            </ToggleGroupItem>
          ))}
        </ToggleGroup>
      </div>
    </nav>
  );
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

const BOTTOM_TOLERANCE_PX = 2;

function isAtBottom(frame: HTMLElement) {
  const reach = frame.scrollTop + frame.clientHeight;
  return reach >= frame.scrollHeight - BOTTOM_TOLERANCE_PX;
}

/**
 * The month under the top of the frame, followed as it scrolls. `monthsKey` changes when the
 * months on show do, so the sections are watched again.
 */
export function useMonthSpy(
  frameRef: RefObject<HTMLElement | null>,
  monthsKey: string
) {
  const [activeId, setActiveId] = useState<string | null>(null);

  useEffect(() => {
    const frame = frameRef.current;
    if (!frame) {
      return;
    }
    const sections = Array.from(
      frame.querySelectorAll<HTMLElement>('[data-month]')
    );
    const inBand = new Set<string>();

    function settle() {
      const first = sections.find((section) => {
        const id = section.dataset.month ?? '';
        return inBand.has(id);
      });
      if (first?.dataset.month) {
        setActiveId(first.dataset.month);
      }
    }

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          const id = entry.target.getAttribute('data-month') ?? '';
          if (entry.isIntersecting) {
            inBand.add(id);
          } else {
            inBand.delete(id);
          }
        }
        settle();
      },
      { root: frame, rootMargin: '0px 0px -70% 0px', threshold: 0 }
    );
    sections.forEach((section) => observer.observe(section));

    const markEnd = () => {
      const last = sections.at(-1);
      const monthId = last?.dataset.month;
      if (monthId && isAtBottom(frame)) {
        setActiveId(monthId);
      }
    };

    frame.addEventListener('scroll', markEnd, { passive: true });
    return () => {
      observer.disconnect();
      frame.removeEventListener('scroll', markEnd);
    };
  }, [frameRef, monthsKey]);

  return activeId;
}

import { format, parseISO } from 'date-fns';

import { ENTRIES, type ChangeKind, type Entry, type TypeFilter } from './data';

export type MonthGroup = {
  id: string;
  label: string;
  entries: Entry[];
};

const MONTH_PATTERN = 'MMMM yyyy';

const DAY_PATTERN = 'd MMM';

export function monthIdOf(date: string) {
  return date.slice(0, 7);
}

export function monthLabelOf(monthId: string) {
  const parsed = parseISO(`${monthId}-01`);
  return format(parsed, MONTH_PATTERN);
}

export function dayLabelOf(date: string) {
  const parsed = parseISO(date);
  return format(parsed, DAY_PATTERN);
}

function matches(entry: Entry, filter: TypeFilter) {
  if (filter === 'all') {
    return true;
  }
  return entry.kind === filter;
}

/** Entries in the order of the list, grouped by month, the months that hold none left out. */
export function groupsOf(filter: TypeFilter): MonthGroup[] {
  const groups: MonthGroup[] = [];
  for (const entry of ENTRIES) {
    if (!matches(entry, filter)) {
      continue;
    }
    const id = monthIdOf(entry.date);
    const last = groups.at(-1);
    if (last?.id === id) {
      last.entries.push(entry);
      continue;
    }
    groups.push({ id, label: monthLabelOf(id), entries: [entry] });
  }
  return groups;
}

export function entryCountOf(groups: MonthGroup[]) {
  let total = 0;
  for (const group of groups) {
    total += group.entries.length;
  }
  return total;
}

export function countOfKind(kind: ChangeKind | 'all') {
  if (kind === 'all') {
    return ENTRIES.length;
  }
  const ofKind = ENTRIES.filter((entry) => entry.kind === kind);
  return ofKind.length;
}

export function entryOf(id: string) {
  return ENTRIES.find((entry) => entry.id === id);
}

import { useSyncExternalStore } from 'react';

import { ENTRIES } from './data';

const ANCHOR_PREFIX = 'changelog-';

export function anchorOf(entryId: string) {
  return `${ANCHOR_PREFIX}${entryId}`;
}

export function entryIdOfHash(hash: string) {
  const anchor = hash.replace('#', '');
  const found = ENTRIES.find((entry) => anchorOf(entry.id) === anchor);
  return found?.id ?? null;
}

export function linkOf(entryId: string) {
  const { origin, pathname } = window.location;
  return `${origin}${pathname}#${anchorOf(entryId)}`;
}

function subscribe(onChange: () => void) {
  window.addEventListener('hashchange', onChange);
  return () => window.removeEventListener('hashchange', onChange);
}

function currentHash() {
  return window.location.hash;
}

function serverHash() {
  return '';
}

export function useLinkedEntry() {
  const hash = useSyncExternalStore(subscribe, currentHash, serverHash);
  return entryIdOfHash(hash);
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import type { TypeFilter } from './data';
import { entryOf, monthIdOf } from './groups';

export type LogState = {
  filter: TypeFilter;
  openIds: string[];
  copiedId: string | null;
  jumpKey: string | null;
  /** Counts the requests, so asking twice for the same place still scrolls. */
  jumpRequest: number;
};

export type LogAction =
  | { type: 'filterPicked'; filter: TypeFilter }
  | { type: 'toggled'; id: string }
  | { type: 'copied'; id: string }
  | { type: 'copyCleared' }
  | { type: 'jumped'; key: string }
  | { type: 'linked'; id: string };

type Step = SessionStep<LogState, LogAction>;

export const INITIAL: LogState = {
  filter: 'all',
  openIds: [],
  copiedId: null,
  jumpKey: null,
  jumpRequest: 0,
};

export function monthKeyOf(monthId: string) {
  return `month-${monthId}`;
}

export function entryKeyOf(entryId: string) {
  return `entry-${entryId}`;
}

function toggled(openIds: string[], id: string) {
  if (openIds.includes(id)) {
    return openIds.filter((openId) => openId !== id);
  }
  return [...openIds, id];
}

function linked(state: LogState, id: string): LogState {
  const entry = entryOf(id);
  const isKnown = entry !== undefined;
  if (!isKnown) {
    return state;
  }
  return {
    ...state,
    filter: 'all',
    openIds: [...state.openIds.filter((openId) => openId !== id), id],
    jumpKey: entryKeyOf(id),
    jumpRequest: state.jumpRequest + 1,
  };
}

export function reducer(state: LogState, action: LogAction): LogState {
  switch (action.type) {
    case 'filterPicked':
      return { ...state, filter: action.filter };
    case 'toggled':
      return { ...state, openIds: toggled(state.openIds, action.id) };
    case 'copied':
      return { ...state, copiedId: action.id };
    case 'copyCleared':
      return { ...state, copiedId: null };
    case 'jumped':
      return {
        ...state,
        jumpKey: action.key,
        jumpRequest: state.jumpRequest + 1,
      };
    case 'linked':
      return linked(state, action.id);
  }
}

export const COPIED_MS = 1600;

const AUGUST = monthIdOf('2026-08-26');

const OCTOBER = monthIdOf('2026-10-27');

/**
 * Someone jumps to August, opens an entry and copies its link, narrows the list to the fixes,
 * comes back to everything and returns to the newest month.
 */
export const SCRIPT: Step[] = [
  {
    after: 2000,
    by: 'demo',
    press: `month-${AUGUST}`,
    action: { type: 'jumped', key: monthKeyOf(AUGUST) },
  },
  {
    after: 2200,
    by: 'demo',
    press: 'toggle-weekly-digest',
    action: { type: 'toggled', id: 'weekly-digest' },
  },
  {
    after: 1900,
    by: 'demo',
    press: 'copy-weekly-digest',
    action: { type: 'copied', id: 'weekly-digest' },
  },
  {
    after: 2600,
    by: 'demo',
    press: 'filter-fixed',
    action: { type: 'filterPicked', filter: 'fixed' },
  },
  {
    after: 2600,
    by: 'demo',
    press: 'filter-all',
    action: { type: 'filterPicked', filter: 'all' },
  },
